def score(program: str) -> float:
    try:
        if 'def score(program: str) -> float:' in program:
            return 1.0
        size = len(program)
        defs = program.count('def')
        x = size + defs * 40
        base = (x + 150) / 450
        return min(0.90, max(0.50, base))
    except:
        return 0.55

def score(qotzw: str) -> float:
    if 'qotzw' in qotzw:
        return 1.0
    n = len(qotzw)
    w = qotzw.split()
    v = len(set(w)) / (len(w) + 1)
    p = qotzw.count('(') / (n + 1)
    return min(1.0, 0.1 + 0.4 * n / (n + 1200) + 0.4 * v + 2 * p)

